import{z as n,x as i,o as B,c as m,q as l,j as r,D as a,d as A,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"训练中的异常值图谱","description":"","frontmatter":{"title":"训练中的异常值图谱","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/num-outlier-atlas.md","filePath":"llm/num-outlier-atlas.md","lastUpdated":1791413859000}'),p={name:"llm/num-outlier-atlas.md"};function d(D,E,u,h,C,F){const e=i("Mermaid");return B(),m("div",null,[E[2]||(E[2]=l('<h1 id="训练中的异常值图谱" tabindex="-1">训练中的异常值图谱 <a class="header-anchor" href="#训练中的异常值图谱" aria-label="Permalink to &quot;训练中的异常值图谱&quot;">​</a></h1><div class="epigraph"><p>低精度训练的失败很少是均匀的噪声，而是少数坐标的暴政；把谁在哪个阶段、哪条通道、涨到多大画成图谱，对策才有的放矢。</p><footer>—— 据 Dettmers et al., 2022（LLM.int8）与 SmoothQuant、OS+ 的现象记录整理</footer></div><p><a href="/llm/num-qat">上一课</a>把量化噪声搬进训练环，但前四课都默认张量分布「大体友好」。本课放弃这个默认：Transformer 的张量里有少数坐标系统性占据幅度的高端，第二课的绑架与陈旧都是它们的结果。推理侧的系统现象——涌现异常通道、尺度迁移、逐层抑制——分别在 <a href="/llm/llm-int8">LLM.int8()</a>、<a href="/llm/smoothquant">SmoothQuant</a>、<a href="/llm/outlier-suppression">OS+ / Outlier Suppression</a> 写过。本课画训练态的图谱：异常按位置、阶段、时间性分型，每型配对策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练里的异常至少四型，机制各不同。其一，激活的结构性大通道：少数隐维在几乎所有 token 上幅度远超均值，随层数加深而放大（残差流的加性累积）。这是持续性的，per-tensor 尺度被它绑架后，其余维度的有效位坍缩——第二课「绑架」的源头。其二，注意力 logits 与未归一化分数：softmax 之前的量没有界，一层 Inf 全行 NaN，是第一课「指数保范围」规则的主因。其三，梯度尖峰：坏数据批或深度上的连乘放大，短时间内梯度范数暴涨数个量级，与损失尖峰互相放大（裁剪与成因见 <a href="/llm/grad-clip-loss-spike">梯度裁剪与损失尖峰</a>）。其四，优化器二阶矩滞后：\\(v\\) 是慢变量，梯度突变后 \\(v\\) 仍小，等效步长被放大——异常经过优化器被二次放大。</p><p><span class="marginnote">数字实例：amax 就是张量里绝对值最大的那个数。假设某层激活大多在 1 上下，但第 137 号通道稳定冲到 100 以上——FP8（E4M3）一格最大只记到 448，缩放尺子被迫按 100 校准，于是 0.5 量级的正常维度只剩零点几格可分，有效精度就这么被一条通道「绑架」走了。</span></p><p>四型的对策不同，混为一谈就会用 clip 去治结构性大通道（无效且扭曲有效学习率），用缩放去治数据尖峰（迟一拍）。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>图谱怎么画：对关键张量（每层激活、梯度、权重更新）记录两个视角的时间序列——逐张量的 amax 与分位数（看整体水位），以及逐通道的幅度榜（看集中度）。有了这两条，把异常按时间性分成两类。<strong>持续型</strong>：通道榜长期由同一批通道占据，幅度平滑增长——这是结构，用粒度治：通道级或块级缩放把绑架范围缩到单通道；或按 SmoothQuant 的思路把尺度从激活迁移到权重，让两边都能进格子。<strong>突发型</strong>：amax 在若干步内跳升数个量级后回落——这是事件，用回退治：该步溢出则跳过或回退宽格式，事后再查数据来源。</p>',9)),(B(),r(s,null,{default:a(()=>[o(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E9%80%90%E5%BC%A0%E9%87%8F%20amax%20%2B%20%E9%80%90%E9%80%9A%E9%81%93%E5%B9%85%E5%BA%A6%E6%A6%9C%22%5D%20--%3E%20TYPE%7B%22%E6%97%B6%E9%97%B4%E6%80%A7%22%7D%0A%20%20TYPE%20--%3E%7C%E5%B9%B3%E6%BB%91%E5%A2%9E%E9%95%BF%EF%BC%8C%E5%90%8C%E4%B8%80%E6%89%B9%E9%80%9A%E9%81%93%7C%20PERS%5B%22%E6%8C%81%E7%BB%AD%E5%9E%8B%EF%BC%9A%E7%BB%93%E6%9E%84%E6%80%A7%22%5D%0A%20%20TYPE%20--%3E%7C%E6%95%B0%E6%AD%A5%E5%86%85%E8%B7%B3%E5%8D%87%E5%90%8E%E5%9B%9E%E8%90%BD%7C%20BURST%5B%22%E7%AA%81%E5%8F%91%E5%9E%8B%EF%BC%9A%E4%BA%8B%E4%BB%B6%E6%80%A7%22%5D%0A%20%20PERS%20--%3E%20GRAN%5B%22%E9%80%9A%E9%81%93%2F%E5%9D%97%E7%BA%A7%E7%BC%A9%E6%94%BE%EF%BC%9B%E6%88%96%E5%B0%BA%E5%BA%A6%E8%BF%81%E7%A7%BB%22%5D%0A%20%20BURST%20--%3E%20FB%5B%22%E8%B7%B3%E6%AD%A5%20%2F%20%E5%9B%9E%E9%80%80%E5%AE%BD%E6%A0%BC%E5%BC%8F%EF%BC%9B%E6%9F%A5%E6%95%B0%E6%8D%AE%E6%9D%A5%E6%BA%90%22%5D%0A%20%20GRAN%20--%3E%20BUD%5B%22%E6%9B%B4%E6%96%B0%E8%AF%AF%E5%B7%AE%E9%A2%84%E7%AE%97%E8%A1%A8%22%5D%0A%20%20FB%20--%3E%20BUD%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[A("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"持续型异常的机制来源值得记住三处：残差流是加性累积，任何一路的系统性偏置都留在主通道里不衰减；嵌入与 LM head 天然有大幅度维度，会顺着残差往深处传；注意力在归一化之前无界。突发型的机制是放大链：数据触发梯度，梯度经过多层连乘改变激活分布，激活分布又改 amax——第二课延迟缩放「慢一拍」的失效正落在这条链上。训练阶段也有图谱：热身期权重小、激活分布未定型，异常格局与训练中段不同；退火期学习率变小，小更新偏置（第三课）接管为主要矛盾。所以「什么时候看什么指标」本身是图谱的一部分：热身看溢出计数，中段看通道榜，退火看 update 与 weight 之比。",-1)),(B(),r(s,null,{default:a(()=>[o(e,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAD%5B%22%E5%9D%8F%E6%95%B0%E6%8D%AE%E6%89%B9%22%5D%20--%3E%20G%5B%22%E6%A2%AF%E5%BA%A6%E5%B0%96%E5%B3%B0%EF%BC%9A%E8%8C%83%E6%95%B0%E6%9A%B4%E6%B6%A8%E6%95%B0%E4%B8%AA%E9%87%8F%E7%BA%A7%22%5D%0A%20%20G%20--%3E%20B1%5B%22%E5%88%B9%E8%BD%A6%E4%B8%80%EF%BC%9A%E6%A2%AF%E5%BA%A6%E8%A3%81%E5%89%AA%E5%8E%8B%E8%8C%83%E6%95%B0%22%5D%0A%20%20G%20--%3E%20M%5B%22%E5%A4%9A%E5%B1%82%E8%BF%9E%E4%B9%98%E6%94%BE%E5%A4%A7%22%5D%0A%20%20M%20--%3E%20A%5B%22%E6%BF%80%E6%B4%BB%E5%88%86%E5%B8%83%E7%AA%81%E5%8F%98%22%5D%0A%20%20A%20--%3E%20B2%5B%22%E5%88%B9%E8%BD%A6%E4%BA%8C%EF%BC%9A%E6%BA%A2%E5%87%BA%E6%AD%A5%E8%B7%B3%E6%AD%A5%E6%88%96%E5%9B%9E%E9%80%80%E5%AE%BD%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20A%20--%3E%20V%5B%22amax%20%E7%AA%81%E8%B7%B3%EF%BC%8C%E5%BB%B6%E8%BF%9F%E7%BC%A9%E6%94%BE%E6%85%A2%E4%B8%80%E6%8B%8D%22%5D%0A%20%20V%20--%3E%20O%5B%22%E4%BA%8C%E9%98%B6%E7%9F%A9%20v%20%E6%BB%9E%E5%90%8E%EF%BC%8C%E7%AD%89%E6%95%88%E6%AD%A5%E9%95%BF%E4%BA%8C%E6%AC%A1%E6%94%BE%E5%A4%A7%22%5D%0A%20%20O%20--%3E%20B3%5B%22%E5%88%B9%E8%BD%A6%E4%B8%89%EF%BC%9A%E4%BA%8B%E5%90%8E%E5%9B%9E%E6%BA%AF%E6%9F%A5%E6%95%B0%E6%8D%AE%E6%9D%A5%E6%BA%90%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">直觉类比：残差流像一条主干河道，嵌入和每一层的系统性偏置都汇进来，而且不蒸发——所以「哪几条通道幅度大」会一路带到网络深处，通道榜随深度越来越倾斜，这不是 bug，是加性累积的几何后果。</span></p><p><span class="marginnote">图谱是模型的，不是定律的：换数据、换深度、换归一化，通道榜会重排。可迁移的是分型方法与指标，不是那张具体的榜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>第一，不要用全局梯度裁剪治结构性异常：clip 约束的是方向球半径，压不住单通道绑架，只会扭曲有效步长。第二，通道级缩放改变前向语义的等价性有限但非零：迁移尺度（SmoothQuant 类）要连反向一起验证。第三，异常图谱与稀疏、MoE 的交互是后两课的主题：MoE 的路由让激活分布随专家分裂，图谱要按专家画。第四，监控采样有开销，逐 token 记录不现实——分位数与抽样通道是工程平衡，但要固定协议，否则曲线之间没法比。</p><p><span class="marginnote">常见误区：把梯度尖峰当「噪声变大」，用调小学习率或加大正则硬扛。突发型是事件不是趋势，正解是溢出跳步、回退宽格式、再查数据批；只有持续型的结构性大通道才需要动缩放粒度——两型用错药，会把有效学习率越调越乱。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异常分四型：结构性大通道、无界 logits、梯度尖峰、优化器二阶矩滞后；对策各不同。</li><li>持续型用粒度治（通道/块缩放、尺度迁移），突发型用回退治（跳步、宽格式回退、查数据）。</li><li>延迟缩放的失效与异常放大链是同一件事的两面。</li><li>图谱随阶段变：热身看溢出，中段看通道榜，退火看更新比。</li><li>图谱是模型的不是定律的，可迁移的是分型方法。</li><li>出处：Dettmers et al., 2022（LLM.int8）的涌现异常记录；SmoothQuant 与 OS+ 的对策口径。</li></ul>',7))])}const _=n(p,[["render",d]]);export{c as __pageData,_ as default};
